function pensionDomainAccepts(domain,value){if(!domain)return true;if(domain.type==='boolean')return typeof value==='boolean';if(domain.type==='enum')return typeof value==='string'&&domain.allowedValues.includes(value);if(domain.type==='integer'){if(!Number.isSafeInteger(value))return false;if(Array.isArray(domain.allowedValues))return domain.allowedValues.includes(value);return (domain.min===undefined||value>=domain.min)&&(domain.max===undefined||value<=domain.max)&&(value-(domain.min||0))%(domain.step||1)===0;}if(Array.isArray(domain.allowedValues))return domain.allowedValues.includes(value);return true;}
