  const grossIncomeCents=sum(byActivity.map(item=>item.grossIncomeCents)),taxableIncomeCents=Math.max(0,grossIncomeCents-payload.taxFacts.deductibleContributionsPaidCents),taxCents=Math.round(taxableIncomeCents*(payload.taxFacts.startupRateRequested?5:15)/100),socialCents=Math.round(grossIncomeCents/10);
  const actualCashCents=Math.max(0,sum(payload.activities.map(item=>item.thresholdCashCents))),expectedCashCents=sum([payload.forecast.expectedReceiptsCents,payload.forecast.newCompensationCents].filter(Number.isInteger)),forecastMissing=expectedCashCents>0&&!payload.forecast.activityKey;
  const eligibility=outcome(payload.year,{eligible:true,immediateExit:false,nextYearExit:false}),income=outcome(payload.year,{grossIncomeCents,deductibleContributionsCents:payload.taxFacts.deductibleContributionsPaidCents,taxableIncomeCents,byActivity}),social=pensionFixtureOutcome(payload,socialCents),tax=outcome(payload.year,{rateBps:payload.taxFacts.startupRateRequested?500:1500,taxCents});
  const advanceMissing=payload.taxFacts.priorYearTaxCents===null||payload.taxFacts.validAdvancesPaidCents===null,advanceTotal=payload.taxFacts.priorYearTaxCents||0,advanceRows=advanceTotal<=5165?[]:advanceTotal<25752?[{number:2,amountCents:advanceTotal,taxCode:'1791'}]:[{number:1,amountCents:Math.round(advanceTotal*.4),taxCode:'1790'},{number:2,amountCents:advanceTotal-Math.round(advanceTotal*.4),taxCode:'1791'}],advances=advanceMissing?outcome(payload.year,null,[{code:'ADVANCE_INPUTS_MISSING',message:'Completa saldo e acconti.'}]):outcome(payload.year,{balance:{debitCents:Math.max(0,taxCents-payload.taxFacts.validAdvancesPaidCents)},installments:advanceRows}),calendarEvents=advanceRows.map(item=>({date:item.number===2?`${payload.year}-11-30`:`${payload.year}-06-30`,entity:'ERARIO',code:item.taxCode,kind:item.number===2?'advance_second_or_single':'balance_or_first_advance',amountCents:item.amountCents,referenceYear:payload.year,status:'planned'}));
