  const calculated=configEnvelope().result.pensionManagements.flatMap(management=>management.years.filter(year=>year.status==='CALCOLABILE').map(year=>({id:management.id,year:year.year,requiredFacts:year.requiredFacts}))),completeOptions={INPS_GS:{otherMandatoryCoverage:false},INPS_ARTIGIANI:{ageRateProfile:'adult',contributionHistory:'post1995',reductionMode:'none'},INPS_COMMERCIANTI:{ageRateProfile:'adult',contributionHistory:'post1995',reductionMode:'none'},ENASARCO:{mandateType:'mono'},CNPADC:{subjectiveRateBps:1200,minimumProfile:'ordinary'},CNPR:{subjectiveRateBps:1500,subjectiveMinimumMode:'full',supplementaryMinimumMode:'full',integrativeMinimumApplies:true},CASSA_GEOMETRI:{minimumProfile:'ordinary'},ENPACL:{rateProfile:'ordinary'},ENPAP:{subjectiveRateBps:1000,subjectiveMinimumCents:85600},EPAP:{subjectiveRateBps:1000,minimumProfile:'ordinary'},INPGI_GS:{minimumProfile:'ordinary'}};assert.equal(calculated.length,15);
