test('Forfettario 10B: layout reale senza overflow a 1440, 1280, 1100, 1024, 390 e 375 px',async t=>{
  const server=await startServer();let browser;t.after(async()=>{if(browser)await browser.close();await server.close();});browser=await chromium.launch({headless:true});
  for(const width of [1440,1280,1100,1024,390,375]){const context=await browser.newContext({locale:'it-IT',viewport:{width,height:920}}),page=await context.newPage(),errors=[];page.on('console',message=>{if(message.type()==='error')errors.push(message.text());});page.on('pageerror',error=>errors.push(error.message));await page.goto(`${server.baseUrl}/tools/forfettario/`,{waitUntil:'load'});await page.waitForFunction(()=>globalThis.ForfettarioAuthoritative.config());const landing=await page.evaluate(()=>({overflow:document.documentElement.scrollWidth-innerWidth,visible:!document.getElementById('startFlow').hidden}));assert.equal(landing.visible,true);assert.ok(landing.overflow<=1,`landing ${width}px`);const menu=page.locator('#startFlow .tal-gh-menu-toggle'),nav=page.locator('#talGhNavStart');if(width<=760){assert.equal(await menu.isVisible(),true,`toggle visibile a ${width}px`);await menu.click();assert.equal(await nav.isVisible(),true,`menu aperto a ${width}px`);await menu.click();}else{assert.equal(await menu.isVisible(),false,`nessun toggle inattivo a ${width}px`);assert.equal(await nav.isVisible(),true,`navigazione visibile a ${width}px`);}await page.locator('#loadDemoStart').click();await page.waitForFunction(()=>!document.getElementById('appShell').hidden&&globalThis.ForfettarioAuthoritative.diagnostics().hasResult);const app=await page.evaluate(()=>({overflow:document.documentElement.scrollWidth-innerWidth,dashboard:document.getElementById('viewDashboard').classList.contains('active'),footer:!!document.querySelector('#appShell .tal-site-footer'),metricWidths:[...document.querySelectorAll('#dashboardMetrics .card')].map(card=>card.getBoundingClientRect().width),clipped:[...document.querySelectorAll('#personalSessionActions button')].some(button=>button.scrollWidth>button.clientWidth+1)}));assert.equal(app.dashboard,true);assert.equal(app.footer,true);assert.ok(app.overflow<=1,`app ${width}px`);assert.equal(app.clipped,false,`azioni non troncate a ${width}px`);assert.ok(app.metricWidths.every(value=>value>120),`metriche leggibili a ${width}px`);assert.deepEqual(errors,[]);await context.close();}
});

test('Forfettario hardening: calendario, denaro, diagnostica, selezioni e conferme TAL',async t=>{
  const server=await startServer();let browser;t.after(async()=>{if(browser)await browser.close();await server.close();});browser=await chromium.launch({headless:true});
  const context=await browser.newContext({locale:'it-IT',viewport:{width:1440,height:1000}}),page=await context.newPage(),nativeDialogs=[],errors=[];
  await page.addInitScript(()=>{const NativeDate=Date;let clock='2026-09-13T12:00:00.000Z';globalThis.__setForfettarioTestDate=value=>{clock=value;};class TestDate extends NativeDate{constructor(...args){super(...(args.length?args:[clock]));}static now(){return new NativeDate(clock).getTime();}}TestDate.parse=NativeDate.parse;TestDate.UTC=NativeDate.UTC;globalThis.Date=TestDate;});
  page.on('dialog',dialog=>{nativeDialogs.push(dialog.type());dialog.dismiss();});page.on('console',message=>{if(message.type()==='error')errors.push(message.text());});page.on('pageerror',error=>errors.push(error.message));
  await page.goto(`${server.baseUrl}/tools/forfettario/`,{waitUntil:'load'});await page.waitForFunction(()=>globalThis.ForfettarioAuthoritative.config());
  const restored=await page.evaluate(async()=>{const app=globalThis.ForfettarioPersonalApp,draft=app.loadDemo();draft.demo=false;draft.taxPlanning.priorYearTaxCents=50000;draft.fiscalYears['2026'].taxPlanning=JSON.parse(JSON.stringify(draft.taxPlanning));return app.restore(JSON.stringify({format:'forfettario-pro-backup-v1',exportedAt:new Date().toISOString(),state:draft}));});
  assert.equal(restored.ok,true,JSON.stringify(restored));await page.waitForFunction(()=>globalThis.ForfettarioAuthoritative.diagnostics().hasResult);

  await page.locator('#workspaceNav [data-view="tax"]').click();await page.waitForFunction(()=>document.getElementById('paymentTimeline').textContent.includes('1791'));
  const septemberTimeline=(await page.locator('#paymentTimeline').innerText()).replace(/\s+/g,' ');
  assert.match(septemberTimeline,/2026-11-30/);assert.match(septemberTimeline,/300,00\s*€/);assert.match(septemberTimeline,/codice 1791/);assert.match(septemberTimeline,/anno di riferimento 2026/);
  assert.match(septemberTimeline,/2027-11-30/);assert.match(septemberTimeline,/anno di riferimento 2027/);
  assert.doesNotMatch(septemberTimeline,/Nessun pagamento/);
  await page.evaluate(()=>globalThis.__setForfettarioTestDate('2026-11-30T12:00:00.000Z'));await page.locator('#workspaceNav [data-view="tax"]').click();assert.match((await page.locator('#paymentTimeline').innerText()).replace(/\s+/g,' '),/anno di riferimento 2026/,'la scadenza resta visibile nel giorno dovuto');
  await page.evaluate(()=>globalThis.__setForfettarioTestDate('2026-12-01T12:00:00.000Z'));await page.locator('#workspaceNav [data-view="tax"]').click();const decemberTimeline=(await page.locator('#paymentTimeline').innerText()).replace(/\s+/g,' ');assert.doesNotMatch(decemberTimeline,/anno di riferimento 2026/);assert.match(decemberTimeline,/anno di riferimento 2027/,'un evento 2027 conserva la propria annualità');
  await page.evaluate(()=>globalThis.__setForfettarioTestDate('2026-09-13T12:00:00.000Z'));

  await page.locator('#workspaceNav [data-view="invoices"]').click();const unpaidId=await page.evaluate(()=>{const s=globalThis.ForfettarioPersonalApp.getState(),paid=new Set(s.ledger.payments.map(item=>item.invoiceId));return s.ledger.invoices.find(item=>!paid.has(item.id)).id;});
  await page.locator(`[data-edit-invoice="${unpaidId}"]`).first().click();await page.locator('#invoiceAmount').fill('9500,25');await page.locator('#saveInvoice').click();await page.waitForFunction(()=>!document.getElementById('invoiceModal').classList.contains('open'));const moneyRow=(await page.locator(`tr:has([data-edit-invoice="${unpaidId}"])`).innerText()).replace(/\s+/g,' ');assert.match(moneyRow,/9\.500,25\s*€/);
  await page.locator('#workspaceNav [data-view="forecast"]').click();await page.locator('#simpleForecast').fill('9500,25');await page.locator('#simpleForecast').press('Tab');assert.equal(await page.locator('#simpleForecast').inputValue(),'9.500,25');await page.locator('#saveForecast').click();await page.waitForFunction(()=>globalThis.ForfettarioPersonalApp.getState().forecast.expectedReceiptsCents===950025);await page.waitForFunction(()=>document.getElementById('forecastMetrics').textContent.includes('9.500,25'));

  await page.locator('#workspaceNav [data-view="invoices"]').click();const paidId=await page.evaluate(()=>globalThis.ForfettarioPersonalApp.getState().ledger.payments[0].invoiceId),beforeOverpayment=await page.evaluate(()=>JSON.stringify(globalThis.ForfettarioPersonalApp.getState()));await page.locator(`[data-edit-invoice="${paidId}"]`).first().click();await page.locator('#invoiceAmount').fill('1,00');await page.locator('#saveInvoice').click();const overpayment=(await page.locator('#invoiceErrors').innerText()).replace(/\s+/g,' '),afterOverpayment=await page.evaluate(()=>JSON.stringify(globalThis.ForfettarioPersonalApp.getState()));assert.equal(afterOverpayment,beforeOverpayment,'il rifiuto non muta lo stato');assert.match(overpayment,/Non puoi ridurre la fattura/);assert.match(overpayment,/1,00\s*€/);assert.match(overpayment,/già incassati/);assert.match(overpayment,/Modifica prima gli incassi collegati/);assert.doesNotMatch(overpayment,/PAYMENT_OVERPAYMENT|Annualità 2025|Annualità 2026/);await page.locator('#invoiceModal [data-close="invoiceModal"]').first().click();

  await page.locator('#workspaceNav [data-view="profile"]').click();await page.locator('#editProfile').click();await page.locator('#onboardNext').click();await page.waitForSelector('.option-card');const optionSemantics=await page.locator('.option-card').evaluateAll(cards=>({allButtons:cards.every(card=>card.tagName==='BUTTON'),allPressed:cards.every(card=>/^(true|false)$/.test(card.getAttribute('aria-pressed')||'')),allNamed:cards.every(card=>!!card.textContent.trim())}));assert.deepEqual(optionSemantics,{allButtons:true,allPressed:true,allNamed:true});const firstOption=page.locator('.option-card').first();await firstOption.focus();await firstOption.press('Space');assert.ok(await page.locator('.option-card[aria-pressed="true"].selected').count()>0);

  await page.reload({waitUntil:'load'});await page.waitForFunction(()=>globalThis.ForfettarioAuthoritative.config()&&!document.getElementById('appShell').hidden);const beforeCancel=await page.evaluate(()=>JSON.stringify(globalThis.ForfettarioPersonalApp.getState()));await page.locator('#newPosition').click();assert.equal(await page.locator('#confirmationModal').isVisible(),true);await page.waitForFunction(()=>document.activeElement.id==='cancelConfirmation');await page.keyboard.press('Escape');assert.equal(await page.locator('#confirmationModal').isVisible(),false);assert.equal(await page.evaluate(()=>JSON.stringify(globalThis.ForfettarioPersonalApp.getState())),beforeCancel);await page.waitForFunction(()=>document.activeElement.id==='newPosition');
  await page.selectOption('#contextYear','2025');assert.equal(await page.locator('#confirmationModal').isVisible(),true);await page.keyboard.press('Escape');assert.equal(await page.evaluate(()=>globalThis.ForfettarioPersonalApp.getState().profile.year),2026,'annullare il cambio annualità non muta lo stato');assert.equal(await page.locator('#contextYear').inputValue(),'2026');await page.waitForFunction(()=>document.activeElement.id==='contextYear');
  await page.selectOption('#contextYear','2025');assert.equal(await page.locator('#confirmationModal').isVisible(),true);assert.match(await page.locator('#confirmConfirmation').innerText(),/2025/);await page.waitForFunction(()=>document.getElementById('confirmationModal').contains(document.activeElement));await page.locator('#confirmConfirmation').click();await page.waitForFunction(()=>globalThis.ForfettarioPersonalApp.getState().profile.year===2025);const storedYear=await page.evaluate(()=>JSON.parse(localStorage.getItem(globalThis.ForfettarioPersonalApp.storageKey)).profile.year);assert.equal(storedYear,2025,'la conferma persiste il cambio annualità');
  await page.locator('#newPosition').click();await page.locator('#confirmConfirmation').click();await page.waitForFunction(()=>!document.getElementById('startFlow').hidden);assert.equal(await page.evaluate(()=>localStorage.getItem(globalThis.ForfettarioPersonalApp.storageKey)),null);
  assert.deepEqual(nativeDialogs,[]);assert.deepEqual(errors,[]);await context.close();
});

test('Forfettario hardening: modal TAL contenute e navigabili a 390 e 375 px',async t=>{
  const server=await startServer();let browser;t.after(async()=>{if(browser)await browser.close();await server.close();});browser=await chromium.launch({headless:true});
  for(const width of [390,375]){const context=await browser.newContext({locale:'it-IT',viewport:{width,height:820}}),page=await context.newPage(),dialogs=[];page.on('dialog',dialog=>{dialogs.push(dialog.type());dialog.dismiss();});await page.goto(`${server.baseUrl}/tools/forfettario/`,{waitUntil:'load'});await page.waitForFunction(()=>globalThis.ForfettarioAuthoritative.config());await page.locator('#loadDemoStart').click();await page.waitForFunction(()=>!document.getElementById('appShell').hidden);await page.selectOption('#contextYear','2025');await page.waitForFunction(()=>document.activeElement.id==='cancelConfirmation');const geometry=await page.locator('#confirmationModal .modal-card').evaluate(card=>{const rect=card.getBoundingClientRect();return {left:rect.left,right:rect.right,top:rect.top,bottom:rect.bottom,viewportWidth:innerWidth,viewportHeight:innerHeight,focusInside:card.closest('[role="dialog"]').contains(document.activeElement),overflow:document.documentElement.scrollWidth-innerWidth};});assert.ok(geometry.left>=0&&geometry.right<=geometry.viewportWidth,`${width}px horizontal modal bounds`);assert.ok(geometry.top>=0&&geometry.bottom<=geometry.viewportHeight,`${width}px vertical modal bounds`);assert.ok(geometry.overflow<=1,`${width}px no horizontal overflow`);assert.equal(geometry.focusInside,true);await page.keyboard.press('Tab');assert.equal(await page.evaluate(()=>document.getElementById('confirmationModal').contains(document.activeElement)),true);await page.keyboard.press('Escape');assert.equal(await page.locator('#confirmationModal').isVisible(),false);assert.deepEqual(dialogs,[]);await context.close();}
});
